export const POSMenuScreen: React.FC = () => {
    const router = useRouter();
    const {
        cart,
        addToCart,
        removeFromCart,
        updateQuantity,
        clearCart,
        cartTotal,
        selectedCustomer,
        isOffline,
        session
    } = usePOS();

    const [activeCategory, setActiveCategory] = useState('all');
    const [searchQuery, setSearchQuery] = useState('');
    const [isDiscountModalOpen, setIsDiscountModalOpen] = useState(false);
    const [customizationProduct, setCustomizationProduct] = useState<POSProduct | null>(null);
    const [isProfileOpen, setIsProfileOpen] = useState(false);

    const {
        incomingCall,
        updateCustomer,
        setDeliveryAddress
    } = usePOS();

    // Auto-open on incoming call for Call Center
    useEffect(() => {
        if (session?.posType === 'CALL_CENTER' && incomingCall && incomingCall.customerId) {
            setIsProfileOpen(true);
        }
    }, [incomingCall, session?.posType]);

    const handleUpdateNotes = (notes: string) => {
        if (selectedCustomer) {
            updateCustomer(selectedCustomer.id, { notes });
        }
    };

    const handleSelectAddress = (addressId: string) => {
        if (selectedCustomer) {
            const addr = selectedCustomer.addresses.find(a => a.id === addressId);
            if (addr) {
                setDeliveryAddress({ id: addr.id, text: addr.text, label: addr.label });
            }
        }
    };

    // Optimized filtering
    const filteredProducts = useMemo(() => {
        return MOCK_PRODUCTS.filter(product => {
            const matchesCategory = activeCategory === 'all' || product.categoryId === activeCategory;
            const matchesSearch = product.name.toLowerCase().includes(searchQuery.toLowerCase()) ||
                product.sku.toLowerCase().includes(searchQuery.toLowerCase());
            return matchesCategory && matchesSearch;
        });
    }, [activeCategory, searchQuery]);

    const handleProductClick = (product: POSProduct) => {
        if (!product.isAvailable) return;

        const hasOptions = (product.variantGroups && product.variantGroups.length > 0) ||
            (product.modifierGroups && product.modifierGroups.length > 0);

        if (hasOptions) {
            setCustomizationProduct(product);
        } else {
            addToCart({
                ...product,
                productId: product.id,
                quantity: 1,
                variants: [],
                modifiers: [],
                notes: ''
            });
        }
    };

    const handleCustomizedAddToCart = (cartItem: any) => {
        addToCart(cartItem);
        setCustomizationProduct(null);
    };

    const handleCheckout = () => {
        if (cart.length > 0) {
            router.push('/pos/payment');
        }
    };

    const taxAmount = cartTotal * 0.1;
    const finalTotal = cartTotal + taxAmount;

    return (
        <div className="pos-screen" style={{ display: 'flex', height: '100vh', overflow: 'hidden' }}>

            {/* 1. VERTICAL CATEGORY BAR */}
            <div style={{
                width: '100px',
                background: 'var(--pos-bg-surface)',
                borderRight: '1px solid var(--pos-border-subtle)',
                display: 'flex',
                flexDirection: 'column',
                alignItems: 'center',
                padding: '16px 0',
                gap: '12px'
            }}>
                <button
                    onClick={() => router.push('/pos/dashboard')}
                    className="pos-category-btn"
                    style={{
                        width: '64px',
                        height: '64px',
                        marginBottom: '16px',
                        background: 'var(--pos-bg-card)',
                        borderRadius: '16px',
                        display: 'flex',
                        alignItems: 'center',
                        justifyContent: 'center'
                    }}
                >
                    <ChevronLeft size={24} color="var(--pos-text-secondary)" />
                </button>

                {MOCK_CATEGORIES.map(cat => (
                    <button
                        key={cat.id}
                        onClick={() => setActiveCategory(cat.id)}
                        className={`pos-category-btn ${activeCategory === cat.id ? 'active' : ''}`}
                        style={{
                            width: '72px',
                            height: '72px',
                            display: 'flex',
                            flexDirection: 'column',
                            alignItems: 'center',
                            justifyContent: 'center',
                            gap: '4px',
                            borderRadius: '16px',
                            transition: 'all 0.2s',
                            padding: '8px',
                            background: activeCategory === cat.id ? 'var(--pos-action-primary)' : 'transparent',
                            color: activeCategory === cat.id ? 'white' : 'var(--pos-text-muted)',
                            border: 'none',
                            cursor: 'pointer'
                        }}
                    >
                        <div style={{ fontSize: '20px' }}>{cat.icon}</div>
                        <div style={{ fontSize: '10px', fontWeight: 700, textTransform: 'uppercase', textAlign: 'center' }}>
                            {cat.name}
                        </div>
                    </button>
                ))}
            </div>

            {/* 2. PRODUCT ZONE */}
            <div style={{ flex: 1, display: 'flex', flexDirection: 'column', background: 'var(--pos-bg-main)' }}>
                {/* Header with Customer & Search */}
                <div style={{
                    padding: '16px 24px',
                    display: 'flex',
                    alignItems: 'center',
                    justifyContent: 'space-between',
                    gap: '24px',
                    borderBottom: '1px solid var(--pos-border-subtle)',
                    background: 'var(--pos-bg-surface)'
                }}>
                    <div style={{ display: 'flex', alignItems: 'center', gap: '16px' }}>
                        <div style={{
                            padding: '10px 16px',
                            background: 'var(--pos-bg-card)',
                            borderRadius: '10px',
                            border: '1px solid var(--pos-border-subtle)',
                            display: 'flex',
                            alignItems: 'center',
                            gap: '12px',
                            cursor: 'pointer'
                        }} onClick={() => {
                            if (selectedCustomer) {
                                setIsProfileOpen(true);
                            } else {
                                router.push('/pos/customer-lookup');
                            }
                        }}>
                            <User size={20} color="var(--pos-action-primary)" />
                            <div>
                                <div style={{ fontSize: '10px', fontWeight: 700, color: 'var(--pos-text-muted)', textTransform: 'uppercase' }}>Customer</div>
                                <div style={{ fontSize: '14px', fontWeight: 700, color: 'var(--pos-text-primary)' }}>
                                    {selectedCustomer?.name || 'Walk-in Guest'}
                                </div>
                            </div>
                        </div>
                        {isOffline && (
                            <div className="pos-badge pos-badge-warning">OFFLINE MODE</div>
                        )}
                        {session?.deliveryAddress && (
                            <div style={{
                                padding: '10px 16px',
                                background: 'rgba(16, 185, 129, 0.1)',
                                borderRadius: '10px',
                                border: '1px solid rgba(16, 185, 129, 0.2)',
                                display: 'flex',
                                alignItems: 'center',
                                gap: '8px'
                            }}>
                                <ShoppingBag size={16} color="#10B981" />
                                <div>
                                    <div style={{ fontSize: '10px', fontWeight: 700, color: '#10B981', textTransform: 'uppercase' }}>Delivery To</div>
                                    <div style={{ fontSize: '12px', fontWeight: 700, color: 'var(--pos-text-primary)' }}>{session.deliveryAddress.label}</div>
                                </div>
                            </div>
                        )}
                    </div>

                    <div style={{ flex: 1, maxWidth: '500px', position: 'relative' }}>
                        <Search size={20} color="var(--pos-text-muted)" style={{ position: 'absolute', left: '16px', top: '50%', transform: 'translateY(-50%)' }} />
                        <input
                            type="text"
                            placeholder="Find product or scan SKU..."
                            value={searchQuery}
                            onChange={(e) => setSearchQuery(e.target.value)}
                            className="pos-input"
                            style={{
                                height: '52px',
                                paddingLeft: '48px',
                                background: 'var(--pos-bg-card)',
                                borderRadius: '12px',
                                border: '1px solid var(--pos-border-subtle)',
                                fontSize: '16px'
                            }}
                        />
                    </div>
                </div>

                {/* Product Grid */}
                <div style={{ flex: 1, padding: '24px', overflowY: 'auto' }}>
                    <div className="pos-products-grid" style={{
                        display: 'grid',
                        gridTemplateColumns: 'repeat(auto-fill, minmax(180px, 1fr))',
                        gap: '16px'
                    }}>
                        {filteredProducts.map(product => (
                            <button
                                key={product.id}
                                onClick={() => handleProductClick(product)}
                                className="pos-card hover-scale"
                                style={{
                                    display: 'flex',
                                    flexDirection: 'column',
                                    padding: '16px',
                                    background: 'var(--pos-bg-surface)',
                                    border: '1px solid var(--pos-border-subtle)',
                                    borderRadius: '16px',
                                    textAlign: 'left',
                                    position: 'relative',
                                    minHeight: '140px'
                                }}
                            >
                                <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'flex-start', marginBottom: '12px' }}>
                                    <div style={{
                                        width: '12px',
                                        height: '12px',
                                        borderRadius: '3px',
                                        border: `2px solid ${product.isVeg ? '#10B981' : '#EF4444'}`,
                                        display: 'flex',
                                        alignItems: 'center',
                                        justifyContent: 'center'
                                    }}>
                                        <div style={{ width: '4px', height: '4px', borderRadius: '50%', background: product.isVeg ? '#10B981' : '#EF4444' }} />
                                    </div>
                                    <div style={{ fontSize: '16px', fontWeight: 800, color: 'var(--pos-action-primary)' }}>
                                        ${product.price.toFixed(2)}
                                    </div>
                                </div>

                                <div style={{ fontSize: '16px', fontWeight: 700, color: 'var(--pos-text-primary)', marginBottom: '4px', lineHeight: 1.2 }}>
                                    {product.name}
                                </div>
                                <div style={{ fontSize: '11px', color: 'var(--pos-text-muted)', fontWeight: 600 }}>
                                    {product.sku}
                                </div>

                                {product.hasVariants && (
                                    <div style={{
                                        marginTop: 'auto',
                                        padding: '4px 0',
                                        borderTop: '1px solid var(--pos-border-subtle)',
                                        display: 'flex',
                                        alignItems: 'center',
                                        gap: '4px',
                                        color: 'var(--pos-text-muted)',
                                        fontSize: '10px',
                                        fontWeight: 700
                                    }}>
                                        <Info size={12} /> CUSTOMIZABLE
                                    </div>
                                )}
                            </button>
                        ))}
                    </div>
                </div>
            </div>

            {/* 3. CART/ORDER PANEL */}
            <div style={{
                width: '420px',
                background: 'var(--pos-bg-surface)',
                borderLeft: '1px solid var(--pos-border-subtle)',
                display: 'flex',
                flexDirection: 'column'
            }}>
                <div style={{ padding: '24px', borderBottom: '1px solid var(--pos-border-subtle)', display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
                    <div style={{ display: 'flex', alignItems: 'center', gap: '12px' }}>
                        <ShoppingBag size={24} color="var(--pos-action-primary)" />
                        <div style={{ fontSize: '20px', fontWeight: 800 }}>Order Items</div>
                    </div>
                    <button onClick={clearCart} style={{ background: 'transparent', border: 'none', color: 'var(--pos-state-error)', fontSize: '13px', fontWeight: 700, cursor: 'pointer' }}>
                        CLEAR ALL
                    </button>
                </div>

                {/* Items List */}
                <div style={{ flex: 1, overflowY: 'auto', padding: '12px' }}>
                    {cart.length === 0 ? (
                        <div style={{ height: '100%', display: 'flex', flexDirection: 'column', alignItems: 'center', justifyContent: 'center', color: 'var(--pos-text-muted)', opacity: 0.5 }}>
                            <LayoutGrid size={64} strokeWidth={1} style={{ marginBottom: '16px' }} />
                            <div style={{ fontSize: '18px', fontWeight: 700 }}>No items in cart</div>
                            <div style={{ fontSize: '14px' }}>Select products on the left</div>
                        </div>
                    ) : (
                        <div style={{ display: 'flex', flexDirection: 'column', gap: '8px' }}>
                            {cart.map((item, idx) => (
                                <div key={`${item.id}-${idx}`} className="pos-card" style={{ padding: '16px', background: 'var(--pos-bg-card)', border: '1px solid var(--pos-border-subtle)' }}>
                                    <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'flex-start', marginBottom: '8px' }}>
                                        <div style={{ flex: 1 }}>
                                            <div style={{ fontSize: '15px', fontWeight: 700, color: 'var(--pos-text-primary)' }}>{item.name}</div>
                                            {item.variants?.map(v => (
                                                <div key={v.groupId} style={{ fontSize: '11px', color: 'var(--pos-text-muted)', fontWeight: 600 }}>• {v.name}</div>
                                            ))}
                                            {item.modifiers?.map(m => (
                                                <div key={m.optionId} style={{ fontSize: '11px', color: 'var(--pos-text-muted)', fontWeight: 600 }}>• {m.name} (x{m.quantity})</div>
                                            ))}
                                        </div>
                                        <div style={{ fontSize: '16px', fontWeight: 800, color: 'var(--pos-text-primary)' }}>
                                            ${(item.price * item.quantity).toFixed(2)}
                                        </div>
                                    </div>

                                    <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
                                        <div className="pos-quantity-control" style={{ background: 'var(--pos-bg-main)', height: '40px' }}>
                                            <button className="pos-qty-btn" onClick={() => updateQuantity(item.id, item.quantity - 1)}>
                                                <Minus size={16} />
                                            </button>
                                            <span className="pos-qty-value" style={{ fontSize: '16px', minWidth: '24px' }}>{item.quantity}</span>
                                            <button className="pos-qty-btn" onClick={() => updateQuantity(item.id, item.quantity + 1)}>
                                                <Plus size={16} />
                                            </button>
                                        </div>
                                        <button onClick={() => removeFromCart(item.id)} style={{ background: 'transparent', border: 'none', color: 'var(--pos-text-muted)', cursor: 'pointer' }}>
                                            <Trash2 size={20} />
                                        </button>
                                    </div>
                                </div>
                            ))}
                        </div>
                    )}
                </div>

                {/* Summary & Checkout */}
                <div style={{
                    padding: '24px',
                    background: 'var(--pos-bg-card)',
                    borderTop: '1px solid var(--pos-border-subtle)',
                    boxShadow: '0 -10px 30px rgba(0,0,0,0.1)'
                }}>
                    <div style={{ marginBottom: '20px', display: 'flex', flexDirection: 'column', gap: '8px' }}>
                        <div style={{ display: 'flex', justifyContent: 'space-between', fontSize: '14px', color: 'var(--pos-text-secondary)' }}>
                            <span>Subtotal</span>
                            <span>${cartTotal.toFixed(2)}</span>
                        </div>
                        <div style={{ display: 'flex', justifyContent: 'space-between', fontSize: '14px', color: 'var(--pos-text-secondary)' }}>
                            <span>Tax (10%)</span>
                            <span>${taxAmount.toFixed(2)}</span>
                        </div>
                        <div style={{ display: 'flex', justifyContent: 'space-between', fontSize: '28px', fontWeight: 900, color: 'var(--pos-text-primary)', marginTop: '4px' }}>
                            <span>Total</span>
                            <span>${finalTotal.toFixed(2)}</span>
                        </div>
                    </div>

                    <div style={{ display: 'flex', gap: '12px', marginBottom: '16px' }}>
                        <button className="pos-btn pos-btn-secondary" style={{ flex: 1, gap: '8px' }}>
                            <Pause size={18} /> HOLD
                        </button>
                        <button
                            className="pos-btn pos-btn-secondary"
                            style={{ flex: 1, gap: '8px' }}
                            onClick={() => setIsDiscountModalOpen(true)}
                        >
                            <Tags size={18} /> DISCOUNT
                        </button>
                    </div>

                    <button
                        onClick={handleCheckout}
                        disabled={cart.length === 0}
                        className="pos-btn pos-btn-primary"
                        style={{
                            height: '72px',
                            fontSize: '20px',
                            fontWeight: 800,
                            display: 'flex',
                            alignItems: 'center',
                            justifyContent: 'center',
                            gap: '12px',
                            background: 'linear-gradient(135deg, var(--pos-action-primary) 0%, #178B8F 100%)'
                        }}
                    >
                        <CreditCard size={24} />
                        CHECKOUT
                        <ChevronRight size={24} style={{ marginLeft: 'auto' }} />
                    </button>
                </div>
            </div>

            {/* Modals */}
            <POSDiscountModal
                isOpen={isDiscountModalOpen}
                onClose={() => setIsDiscountModalOpen(false)}
                onApplyDiscount={() => setIsDiscountModalOpen(false)}
            />
            <ProductCustomizationModal
                isOpen={!!customizationProduct}
                product={customizationProduct}
                onClose={() => setCustomizationProduct(null)}
                onAddToCart={handleCustomizedAddToCart}
            />
            <CustomerProfilePanel
                isOpen={isProfileOpen}
                onClose={() => setIsProfileOpen(false)}
                customer={selectedCustomer || null}
                onUpdateNotes={handleUpdateNotes}
                onSelectAddress={handleSelectAddress}
            />
        </div>
    );
};

export default POSMenuScreen;
